// 1. 领域事件定义：不可变，过去时命名，自带全局唯一 eventId
public class OrderCreatedEvent {
    private final String orderId;
    private final String customerId;
    private final BigDecimal totalAmount;
    private final LocalDateTime occurredAt;  // 业务时间戳
    private final String eventId;            // 全局唯一，幂等消费依据

    public OrderCreatedEvent(String orderId, String customerId, BigDecimal total) {
        this.orderId = orderId;
        this.customerId = customerId;
        this.totalAmount = total;
        this.occurredAt = LocalDateTime.now();
        this.eventId = UUID.randomUUID().toString();
    }
}

// 2. 业务事务：写业务表 + 写 outbox 表在同一 @Transactional 内，保证原子
@Component
public class OrderDomainService {
    private final OrderRepository orderRepo;
    private final OutboxRepository outboxRepo;

    @Transactional
    public OrderId createOrder(CreateOrderCmd cmd) {
        Order order = Order.create(cmd);
        orderRepo.save(order);
        outboxRepo.save(new OrderCreatedEvent(
            order.getId(), order.getCustomerId(), order.getTotalAmount()
        ));
        return order.getId();
    }
}

// 3. Outbox Relay：轮询未发布事件，Kafka 确认后才标记 published
@Component
public class OutboxRelay {
    private final OutboxRepository outboxRepo;
    private final KafkaTemplate<String, String> kafka;

    @Scheduled(fixedDelay = 100)
    public void relay() {
        List<OutboxRow> batch = outboxRepo.findUnpublished(100);
        for (OutboxRow row : batch) {
            kafka.send("order-events", row.getAggregateId(), row.getPayload())
                .whenComplete((result, ex) -> {
                    if (ex == null) {
                        outboxRepo.markPublished(row.getEventId());
                    }
                });
        }
    }
}

// 4. 幂等消费：eventId 查去重表，已处理直接跳过
@Component
public class IdempotentInventoryConsumer {
    private final ProcessedEventRepository processedRepo;

    @KafkaListener(topics = "order-events", groupId = "inventory")
    public void onOrderCreated(OrderCreatedEvent event) {
        if (processedRepo.exists(event.getEventId())) {
            return;  // 重复事件，直接忽略
        }
        inventoryService.deduct(event.getOrderId(), event.getItems());
        processedRepo.markProcessed(event.getEventId());
    }
}

// 5. Saga 补偿：扣库存失败时发布反向事件触发释放
@Component
public class OrderCreatedSagaHandler {
    private final ApplicationEventPublisher events;

    @EventListener
    public void handle(OrderCreatedEvent event) {
        try {
            inventoryService.deduct(event.getOrderId(), event.getItems());
        } catch (InsufficientStockException e) {
            events.publishEvent(
                new InventoryDeductFailedEvent(event.getOrderId(), e.getMessage())
            );
        }
    }
}
